export const generateCondition = (category, keyword = '', maxCount = 1) => {
  const baseData = {
    line: ['Line-A', 'Line-B', 'Line-C', 'Line-D'],
    process: ['Photo', 'Etch', 'Clean', 'Diff', 'CMP', 'Ion-Imp'],
    partid: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    product: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    equip: ['EQP-01', 'EQP-02', 'EQP-03', 'EQP-04', 'EQP-05'],
    lottype: ['Production', 'Test', 'Engineer', 'Rework'],
    step: ['HS010092-01', 'HS010092-02', 'HS010093-01', 'HS010094-01'],
    lot: ['LOT-ID-001', 'LOT-ID-002', 'LOT-ID-003', 'LOT-ID-004', 'LOT-ID-005'],
    wafer: ['W01', 'W02', 'W03', 'W04', 'W05', 'W06', 'W07', 'W08', 'W09', 'W10'],
    item: [
      'Thickness',
      'Critical Dimension',
      'Overlay',
      'Defect Count',
      'Temperature',
      'Pressure',
      'Flow Rate',
      'Humidity',
    ],
  };

  const list = [];
  let source = baseData[category] || ['Unknown'];
  if (category === 'y1item' || category === 'y2item') {
    source = baseData['item'];
  }

  for (let i = 1; i <= 20; i++) {
    const baseValue = source[i % source.length];
    const indexStr = String(i).padStart(3, '0');

    let finalItem;

    // --- 카테고리별 데이터 구조 정의 ---
    if ((category === 'step' || category === 'y1item' || category === 'y2item') && maxCount > 1) {
      // step인 경우 객체 형태로 생성 (실제 데이터 + 테스트 설명)
      finalItem = {
        [category]: `${baseValue}-${indexStr}`,
        desc: `test용 ${category} ${indexStr}`,
      };
    } else if (category === 'lot') {
      finalItem = `${baseValue}.W${String(i).padStart(2, '0')}`;
    } else {
      finalItem = `${baseValue}_${indexStr}`;
    }

    // --- 필터링 로직 (문자열 및 객체 대응) ---
    if (!keyword || keyword.length === 0) {
      list.push(finalItem);
    } else {
      // 필터링 기준값 설정: 객체면 step 필드, 아니면 자기 자신
      const targetValue = category === 'step' ? finalItem.step : finalItem;
      const isMatch = keyword.some((k) => targetValue.toLowerCase().includes(k.toLowerCase()));

      if (isMatch) list.push(finalItem);
    }
  }

  return list;
};
