import React, { useRef, useState, useEffect, useMemo } from 'react';
import { flexRender, getCoreRowModel, useReactTable } from '@tanstack/react-table';
import { generateDies } from '../utils/DieGenerator';
import GradientChart from '../chart/GradientChart';
import MetroMap from '../map/MetroMap';
import GradientMap from '../map/GradientMap';
import StatusLegend from '../map/Legend';

const GalleryMetro = ({ params, dataType, colors, onInfoUpdate }) => {
  const scrollRef = useRef(null);
  const [metroDataList, setMetroDataList] = useState([]);

  // --- 확대 관련 상태 ---
  const [zoomIndex, setZoomIndex] = useState(null); // 어떤 데이터셋인지
  const [zoomType, setZoomType] = useState(null); // 'MAP' 또는 'CHART'
  const [activeMapProps, setActiveMapProps] = useState(null); // 맵 확대 시 정보 저장
  const [activeChartProps, setActiveChartProps] = useState(null); // 차트 확대 시 정보 저장

  const [activeTab, setActiveTab] = useState('info');
  const [zoomScale, setZoomScale] = useState(1);
  const [zoomOffset, setZoomOffset] = useState({ x: 0, y: 0 });
  const [isZoomInMode, setIsZoomInMode] = useState(false);
  const [interactionMode, setInteractionMode] = useState('select');

  const [mapContainerSize, setMapContainerSize] = useState(600); // 기본값
  const wrapperRef = useRef(null);

  useEffect(() => {
    // 오버레이(zoomIndex !== null)가 활성화되었을 때만 측정을 시작하도록 트리거를 걸 수도 있습니다.
    if (!wrapperRef.current || zoomIndex === null) return;

    const updateSize = () => {
      if (wrapperRef.current) {
        const width = wrapperRef.current.clientWidth;
        const height = wrapperRef.current.clientHeight;
        // 컨테이너 안에 꽉 차게 그리되, 정사각형 유지를 위해 작은 쪽을 선택
        // 여백(padding)을 고려하여 20~40px 정도를 뺍니다.
        const size = Math.min(width, height);
        if (size > 0) setMapContainerSize(size);
      }
    };

    const ro = new ResizeObserver(() => {
      // requestAnimationFrame을 사용하여 브라우저 렌더링 주기에 맞춰 업데이트
      window.requestAnimationFrame(updateSize);
    });

    ro.observe(wrapperRef.current);
    updateSize(); // 초기 실행

    return () => ro.disconnect();
  }, [zoomIndex, zoomType]);

  const asideWidth = 300;

  // 데이터 생성 (기존 로직 유지)
  useEffect(() => {
    const waferkey = [];
    if (!params.filters) return;
    for (const lot of params.filters.lot || []) {
      waferkey.push({
        lotid: lot.split('.')[0],
        waferid: lot.split('.')[1],
      });
    }
    setMetroDataList(waferkey.map((key) => generateDies(params, key)));
    if (scrollRef.current) {
      scrollRef.current.scrollLeft = 0;

      // 만약 데이터가 많아 렌더링 시간이 걸린다면
      // 아래와 같이 브라우저 다음 프레임에서 실행되도록 할 수 있습니다.
      // requestAnimationFrame(() => {
      //   scrollRef.current.scrollLeft = 0;
      // });
    }
  }, [params, dataType]);

  // 확대 핸들러
  const handleOpenMap = (idx, mapProps) => {
    setZoomType('MAP');
    setZoomIndex(idx);
    setActiveMapProps(mapProps);
  };

  const handleOpenGradient = (idx, gradientProps) => {
    setZoomType('GRADIENT'); // 새로운 타입 정의
    setZoomIndex(idx);
    setActiveChartProps(gradientProps);
    setActiveTab('data'); // 데이터 탭 우선 표시
  };

  const handleOpenChart = (idx, chartProps) => {
    setZoomType('CHART');
    setZoomIndex(idx);
    setActiveChartProps(chartProps);
    setActiveTab('data'); // 차트는 범례가 없으므로 바로 Data 탭으로
  };

  const handleCloseDetail = () => {
    setZoomIndex(null);
    setZoomType(null);
    setActiveMapProps(null);
    setActiveChartProps(null);
    setZoomScale(1);
    setZoomOffset({ x: 0, y: 0 });
    setIsZoomInMode(false);
  };

  const handleWheel = (e) => {
    if (scrollRef.current && zoomIndex === null) {
      scrollRef.current.scrollLeft += e.deltaY;
    }
  };

  // --- 확대 모드 데이터 준비 ---
  const currentWafer = zoomIndex !== null ? metroDataList[zoomIndex] : null;
  const tableData = useMemo(() => {
    if (!currentWafer) return [];
    return params.mapType === 'EDS' || params.mapType === 'MEASURE'
      ? currentWafer.dieList
      : currentWafer.dataList;
  }, [currentWafer, params.mapType]);

  const columns = useMemo(
    () => [
      { header: 'ID', accessorKey: 'id' },
      { header: 'X', accessorKey: 'x', cell: (i) => i.getValue()?.toFixed(0) },
      { header: 'Y', accessorKey: 'y', cell: (i) => i.getValue()?.toFixed(0) },
      { header: 'Value', accessorKey: 'cdvalue', cell: (i) => i.getValue()?.toFixed(2) },
    ],
    [],
  );

  const table = useReactTable({ data: tableData, columns, getCoreRowModel: getCoreRowModel() });

  return (
    <div style={galleryOuterStyle}>
      <div
        ref={scrollRef}
        onWheel={handleWheel}
        style={{
          display: 'grid',
          gridTemplateRows: 'repeat(3, 268px)',
          gridAutoFlow: 'column',
          gridAutoColumns: '350px',
          gap: '5px',
          overflowX: 'auto',
          padding: '5px',
          backgroundColor: '#f8fafc',
          opacity: zoomIndex !== null ? 0.2 : 1,
          pointerEvents: zoomIndex !== null ? 'none' : 'auto', // 확대 시 배경 클릭 방지
        }}
      >
        {metroDataList.map((data, idx) => (
          <React.Fragment key={idx}>
            {params.views.includes('wafer') && (
              <>
                <MapCard
                  data={data}
                  onDoubleClick={() => handleOpenMap(idx, { key: 'Wafer' })}
                  title={data.lotid}
                  params={params}
                />
                <ChartCard
                  dataList={data.dataList}
                  title="Wafer X vs CD"
                  xKey="x"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Wafer X vs CD', xKey: 'x', yKey: 'cdvalue' })
                  }
                />
                <ChartCard
                  dataList={data.dataList}
                  title="Wafer Y vs CD"
                  xKey="y"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Wafer Y vs CD', xKey: 'y', yKey: 'cdvalue' })
                  }
                />
              </>
            )}
            {params.views.includes('radius') && (
              <>
                <MapCard
                  data={data}
                  onDoubleClick={() => handleOpenMap(idx, { key: 'radius' })}
                  title={data.lotid}
                  params={params}
                />
                <ChartCard
                  dataList={data.dataList}
                  style={{ gridRow: '2 / 4' }}
                  title="Radius vs CD"
                  xKey="radius"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Radius vs CD', xKey: 'radius', yKey: 'cdvalue' })
                  }
                />
              </>
            )}
            {params.views.includes('shot') && (
              <>
                <GradientCard
                  data={data.dataList}
                  params={{ ...params, shotxCount: 3, shotyCount: 3 }}
                  drawType="shot"
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenGradient(idx, { title: data.lotid + ' - Shot Map', key: 'shot' })
                  }
                  title={data.lotid + ' - Shot Map'}
                />
                <ChartCard
                  dataList={data.dataList}
                  title="Shot X vs CD"
                  xKey="shotx"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Shot X vs CD', xKey: 'shotx', yKey: 'cdvalue' })
                  }
                />
                <ChartCard
                  dataList={data.dataList}
                  title="Shot Y vs CD"
                  xKey="shoty"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Shot Y vs CD', xKey: 'shoty', yKey: 'cdvalue' })
                  }
                />
              </>
            )}
            {params.views.includes('chip') && (
              <>
                <GradientCard
                  data={data.dataList}
                  params={{ ...params, shotxCount: 3, shotyCount: 3 }}
                  drawType="chip"
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenGradient(idx, { title: data.lotid + ' - Chip Map', key: 'chip' })
                  }
                  title={data.lotid + ' - Chip Map'}
                />
                <ChartCard
                  dataList={data.dataList}
                  title="Chip X vs CD"
                  xKey="chipx"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Chip X vs CD', xKey: 'chipx', yKey: 'cdvalue' })
                  }
                />
                <ChartCard
                  dataList={data.dataList}
                  title="Chip Y vs CD"
                  xKey="chipy"
                  yKey="cdvalue"
                  polyOrder={params.polyOrder || 5}
                  pointSize={params.pointSize || 5}
                  pointStyle={params.pointStyle || 'circle'}
                  colors={params.colors || []}
                  onDoubleClick={() =>
                    handleOpenChart(idx, { title: 'Chip Y vs CD', xKey: 'chipy', yKey: 'cdvalue' })
                  }
                />
              </>
            )}
          </React.Fragment>
        ))}
      </div>

      {/* 통합 확대 오버레이 */}
      {zoomIndex !== null && (
        <div style={zoomOverlayStyle} onDoubleClick={handleCloseDetail}>
          <div style={zoomContainerStyle} onDoubleClick={handleCloseDetail}>
            <div style={zoomHeaderStyle}>
              <span>
                <b>{zoomType === 'MAP' ? 'Wafer Map' : activeChartProps?.title}</b> -{' '}
                {currentWafer.dieList[0]?.lotid}
              </span>
              <div style={modeGroupContainer}>
                {zoomType === 'MAP' && (
                  <>
                    <button onClick={() => setIsZoomInMode(!isZoomInMode)} style={controlBtnStyle}>
                      🔍 ZoomBox
                    </button>
                    <button
                      onClick={() => {
                        setZoomScale(1);
                        setZoomOffset({ x: 0, y: 0 });
                      }}
                      style={controlBtnStyle}
                    >
                      🔄 Zoom Fit
                    </button>
                  </>
                )}
                <button onClick={handleCloseDetail} style={closeBtnStyle}>
                  ✕ Close
                </button>
              </div>
            </div>

            <div style={zoomBodyStyle}>
              <div ref={wrapperRef} style={zoomMapWrapper}>
                {zoomType === 'MAP' ? (
                  <MetroMap
                    params={{ ...params, waferPixelSize: mapContainerSize }}
                    waferDatas={currentWafer}
                    isDetail={true}
                    zoomScale={zoomScale}
                    zoomOffset={zoomOffset}
                    isZoomInMode={isZoomInMode}
                    interactionMode={interactionMode} // 추가된 상태값 전달
                    onZoomChange={(s, o) => {
                      setZoomScale(s);
                      setZoomOffset(o);
                      setIsZoomInMode(false);
                    }}
                  />
                ) : zoomType === 'GRADIENT' ? (
                  <div
                    style={{
                      width: '100%',
                      height: '100%',
                      display: 'flex',
                      justifyContent: 'center',
                      alignItems: 'center',
                      padding: '40px', // 여백을 충분히 주어 맵이 꽉 차는 답답함을 해소
                      boxSizing: 'border-box',
                    }}
                  >
                    <div
                      style={{
                        // 핵심 수정: 고정 100% 대신 auto와 max를 조합
                        width: '750px',
                        aspectRatio: '1 / 1',
                        // flex 부모 안에서 자식이 찌그러지지 않게 방지
                        flexShrink: 0,
                        // 내부 캔버스가 이 영역을 꽉 채우도록 설정
                        display: 'block',
                      }}
                    >
                      <GradientMap
                        params={{ ...params, shotxCount: 3, shotyCount: 3 }}
                        data={currentWafer.dataList}
                        type={activeMapProps?.key || 'shot'}
                        colors={params.colors || []}
                      />
                    </div>
                  </div>
                ) : (
                  <div style={{ width: '90%', height: '90%', position: 'relative' }}>
                    {activeChartProps && (
                      <GradientChart
                        dataList={currentWafer.dataList || []}
                        xKey={activeChartProps.xKey}
                        yKey={activeChartProps.yKey}
                        polyOrder={params.polyOrder || 5}
                        pointSize={params.pointSize || 5}
                        pointStyle={params.pointStyle || 'circle'}
                        colors={params.colors || []}
                      />
                    )}
                  </div>
                )}
              </div>
              <div style={splitterStyle} />
              <aside style={{ ...zoomSidebarStyle, width: asideWidth }}>
                <div style={tabGroupStyle}>
                  {zoomType === 'MAP' && (
                    <button
                      onClick={() => setActiveTab('info')}
                      style={activeTab === 'info' ? activeTabActive : tabBtn}
                    >
                      Info
                    </button>
                  )}
                  <button
                    onClick={() => setActiveTab('data')}
                    style={activeTab === 'data' ? activeTabActive : tabBtn}
                  >
                    Data
                  </button>
                </div>
                <div style={tabContentStyle}>
                  {activeTab === 'info' && zoomType === 'MAP' ? (
                    <StatusLegend items={[]} title="Summary" />
                  ) : (
                    <div style={tableContainer}>
                      <table style={tableStyle}>
                        <thead>
                          {table.getHeaderGroups().map((hg) => (
                            <tr key={hg.id}>
                              {hg.headers.map((h) => (
                                <th key={h.id} style={thStyle}>
                                  {flexRender(h.column.columnDef.header, h.getContext())}
                                </th>
                              ))}
                            </tr>
                          ))}
                        </thead>
                        <tbody>
                          {table.getRowModel().rows.map((row) => (
                            <tr key={row.id} style={trRow}>
                              {row.getVisibleCells().map((c) => (
                                <td key={c.id} style={tdCell}>
                                  {flexRender(c.column.columnDef.cell, c.getContext())}
                                </td>
                              ))}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </aside>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- 서브 컴포넌트 ---
const MapCard = ({ data, onDoubleClick, title, params, drawType }) => (
  <div style={cardStyle} onDoubleClick={onDoubleClick}>
    <div style={titleStyle}>{title}</div>
    <div style={contentWrapperStyle}>
      <MetroMap params={{ ...params, waferPixelSize: 280 }} drawType={drawType} waferDatas={data} />
    </div>
  </div>
);

const GradientCard = ({ params, data, drawType, colors, onDoubleClick, title }) => (
  <div style={cardStyle} onDoubleClick={onDoubleClick}>
    <div style={titleStyle}>{title}</div>
    <div
      style={{
        ...contentWrapperStyle,
        display: 'grid', // 중앙 배치를 위한 그리드
        placeItems: 'center', // 가로/세로 모두 중앙 정렬
        padding: '10px', // 테두리 여백
        overflow: 'hidden', // 영역 이탈 방지
      }}
    >
      {/* 실제 맵이 그려지는 정사각형 컨테이너 */}
      <div
        style={{
          width: '100%',
          height: '100%',
          aspectRatio: '1 / 1', // 가로세로 1:1 고정
          maxHeight: '100%', // 부모 높이보다 커지지 않게
          maxWidth: '100%', // 부모 너비보다 커지지 않게
        }}
      >
        <GradientMap params={params} data={data} type={drawType} colors={colors} />
      </div>
    </div>
  </div>
);

const ChartCard = ({
  dataList,
  title,
  xKey,
  yKey,
  polyOrder,
  pointSize,
  pointStyle,
  colors,
  onDoubleClick,
  style,
}) => (
  <div style={{ ...cardStyle, ...style }} onDoubleClick={onDoubleClick}>
    <div style={titleStyle}>{title}</div>
    <div style={contentWrapperStyle}>
      <GradientChart
        dataList={dataList || []}
        xKey={xKey}
        yKey={yKey}
        polyOrder={polyOrder}
        pointSize={pointSize}
        pointStyle={pointStyle}
        colors={colors}
      />
    </div>
  </div>
);

// 스타일 상수는 이전과 동일 (상략)
const galleryOuterStyle = {
  width: '100%',
  height: '100%',
  position: 'relative',
  overflow: 'hidden',
};
const cardStyle = {
  height: '250',
  backgroundColor: '#fff',
  border: '1px solid #e2e8f0',
  borderRadius: '8px',
  display: 'flex',
  flexDirection: 'column',
  overflow: 'hidden',
  cursor: 'pointer',
};
const titleStyle = {
  fontSize: '10px',
  fontWeight: 'bold',
  color: '#64748b',
  padding: '4px 8px',
  backgroundColor: '#f1f5f9',
  borderBottom: '1px solid #e2e8f0',
  textAlign: 'center',
};
const contentWrapperStyle = {
  flex: 1,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  overflow: 'hidden',
};
const zoomOverlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'rgba(255,255,255,0.95)',
  zIndex: 2000,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
};
const zoomContainerStyle = {
  width: '95%',
  height: '90%',
  backgroundColor: '#fff',
  boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)',
  border: '1px solid #e2e8f0',
  display: 'flex',
  flexDirection: 'column',
};
const zoomHeaderStyle = {
  padding: '12px 20px',
  borderBottom: '1px solid #e2e8f0',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
};
const zoomBodyStyle = { flex: 1, display: 'flex', minHeight: 0 };
const zoomMapWrapper = {
  flex: 1,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  backgroundColor: '#f8fafc',
};
const splitterStyle = { width: '1px', backgroundColor: '#e2e8f0' };
const zoomSidebarStyle = { display: 'flex', flexDirection: 'column', backgroundColor: '#fff' };
const tabGroupStyle = { display: 'flex', borderBottom: '1px solid #e2e8f0' };
const tabBtn = {
  flex: 1,
  padding: '12px',
  border: 'none',
  background: 'none',
  cursor: 'pointer',
  fontSize: '12px',
};
const activeTabActive = {
  ...tabBtn,
  color: '#3b82f6',
  fontWeight: 'bold',
  borderBottom: '2px solid #3b82f6',
};
const tabContentStyle = { flex: 1, overflowY: 'auto', padding: '10px' };
const tableContainer = { width: '100%' };
const tableStyle = { width: '100%', borderCollapse: 'collapse', fontSize: '11px' };
const thStyle = {
  textAlign: 'left',
  padding: '8px',
  borderBottom: '1px solid #e2e8f0',
  backgroundColor: '#f8fafc',
};
const trRow = { borderBottom: '1px solid #f1f5f9' };
const tdCell = { padding: '6px 8px' };
const modeGroupContainer = { display: 'flex', gap: '8px' };
const controlBtnStyle = {
  padding: '4px 12px',
  cursor: 'pointer',
  border: '1px solid #e2e8f0',
  borderRadius: '4px',
  fontSize: '12px',
  backgroundColor: '#fff',
};
const closeBtnStyle = {
  padding: '4px 12px',
  cursor: 'pointer',
  border: '1px solid #3b82f6',
  borderRadius: '4px',
  backgroundColor: '#3b82f6',
  color: '#fff',
};

export default GalleryMetro;
