import React from 'react';

const ColorRowList = ({
  colors = [
    '#ff0000',
    '#ff7f00',
    '#ffff00',
    '#00ff00',
    '#0000ff',
    '#4b0082',
    '#8b00ff',
    '#352a87',
    '#0ec4d1',
    '#f9fb0e',
  ],
  step = 10,
}) => {
  // 1개 행의 높이 정의
  const ROW_HEIGHT = 25;
  // 10개만 보여줄 높이 계산
  const VISIBLE_ROWS = 10;
  const SCROLL_HEIGHT = ROW_HEIGHT * VISIBLE_ROWS;

  return (
    <div style={listContainerStyle}>
      <div style={headerStyle}>Color Steps ({step})</div>

      {/* 스크롤 영역에 계산된 높이 적용 */}
      <div style={{ ...scrollAreaStyle, height: `${SCROLL_HEIGHT}px` }}>
        {colors.map((hex, index) => (
          <div key={index} style={{ ...rowStyle, height: `${ROW_HEIGHT}px` }}>
            {/* 색상 블록 */}
            <div
              style={{
                width: '50px',
                height: '100%', // 부모(rowStyle) 높이를 꽉 채움
                backgroundColor: hex,
                margin: 0,
                border: 'none',
              }}
            />

            {/* 정보 텍스트 */}
            <div style={infoAreaStyle}>
              <span style={indexStyle}>{String(index + 1).padStart(2, '0')}</span>
              <span style={hexTextStyle}>{hex.toUpperCase()}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// --- 스타일 정의 ---

const listContainerStyle = {
  width: '240px',
  border: '1px solid #cbd5e1',
  borderRadius: '8px',
  backgroundColor: '#ffffff',
  overflow: 'hidden',
  display: 'flex',
  flexDirection: 'column',
};

const headerStyle = {
  padding: '10px',
  backgroundColor: '#f8fafc',
  borderBottom: '1px solid #e2e8f0',
  fontSize: '13px',
  fontWeight: 'bold',
  textAlign: 'center',
};

const scrollAreaStyle = {
  overflowY: 'auto', // 세로 스크롤 활성화
  display: 'flex',
  flexDirection: 'column',
  // 스크롤바가 생겨도 디자인이 깨지지 않게 설정
  scrollbarWidth: 'thin',
};

const rowStyle = {
  display: 'flex',
  alignItems: 'center',
  margin: 0,
  padding: 0,
  border: 'none',
  flexShrink: 0, // 높이가 줄어들지 않도록 고정
};

const infoAreaStyle = {
  flex: 1,
  display: 'flex',
  alignItems: 'center',
  height: '100%',
  paddingLeft: '12px',
  borderBottom: '1px solid #f1f5f9',
};

const indexStyle = {
  fontSize: '10px',
  color: '#94a3b8',
  fontFamily: 'monospace',
  marginRight: '10px',
};

const hexTextStyle = {
  fontSize: '11px',
  fontFamily: 'monospace',
  color: '#475569',
};

export default ColorRowList;
