import React, { useState, useRef, useEffect } from 'react';

const HeaderMenu = ({ onMenuType, onDataType }) => {
  const [activeMenu, setActiveMenu] = useState('Monitoring');
  const [hoveredItem, setHoveredItem] = useState(null);
  const [tooltipPos, setTooltipPos] = useState({ left: '50%', transform: 'translateX(-50%)' });
  const containerRefs = useRef({}); // 각 메뉴의 위치를 참조

  const menuItems = [
    {
      id: 'Monitoring',
      label: 'Monitoring',
      tip: [
        '실시간 설비 가동 상태 및 알람을 데이터를 취합하여(DB 데이터) 모니터링합니다.',
        '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
        'Line ~ Y2Item 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
        'Engine은 현재 eChart만 지원합니다.',
        'Type은 차트 종류로 scatter, line, boxplot 지원합니다.',
        'cols는 차트 열배치 숫자입니다.',
        'Add, Remove, Save는 현재 지원 안합니다.',
        'Run 버튼 클릭 Chart와 Output이 생성됩니다. -> 데이터는 Random 생성됩니다.',
        '차트는 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
      ],
    },
    {
      id: 'Map',
      label: 'Wafer Map',
      tip: [
        '웨이퍼의 공간적 데이터 분포를 시각적으로 확인합니다.',
        '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
        'Wafer Geometry는 Wafer Die(Chip) 생성 조건입니다. DieSize 조정시 각기 다른 Die(Chip)가 생성됩니다.',
        'Line ~ LOT.WAFER 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
        'columns는 Wafer Map의 열배치 숫자입니다.',
        'Map Type은 Map 종류로 EDS(bin), MEASURE, DEFECT, METRO-CD Map을 지원합니다.',
        'Draw Wafer Maps 버튼 클릭 Wafer Map Gallery로 생성됩니다. -> 데이터는 Random 생성됩니다.',
        'Map은 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
        'Map은 확대모드에서 Zoom Box 기능 지원합니다.',
      ],
    },
    {
      id: 'Metro',
      label: 'Massive Metrology CD',
      tip: [
        '대량 계측 데이터 기반의 Critical Dimension을 분석합니다.',
        '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
        'Wafer Geometry는 Wafer Die(Chip) 생성 조건입니다. DieSize 조정시 각기 다른 Die(Chip)가 생성됩니다.',
        'Line ~ LOT.WAFER 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
        'Poly Order는 X,Y radius Gradient Chart의 Polynomial Trend의 차수를 조정합니다. -> 차수에 따라 Trend Line 변경됩니다.',
        'Point Size는 Chart의 Point Size를 설정합니다. -> Shot, Chip Map은 지원 안합니다.',
        'Point Style은 Map, Chart의 Point Style을 설정합니다. -> Shot, Chip Map은 지원 안합니다.',
        'View는 Map, X Gradient Chart, Y Gradient Chart Row 세트의 표시 기준을 설정합니다.',
        'Draw Wafer Maps And Gradient Chart 버튼 클릭시 view 선택 기준의 Map, X Gradient Chart, Y Gradient Chart Row 세트가 열 배치로 생성됩니다. -> 데이터는 Random 생성됩니다.',
        'Map, 차트 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
      ],
    },
    { id: 'About', label: 'Information', tip: '시스템 버전 및 릴리즈 정보를 확인합니다.' },
  ];

  // 툴팁 위치 최적화 로직
  const handleMouseEnter = (id) => {
    setHoveredItem(id);
    const element = containerRefs.current[id];
    if (element) {
      const rect = element.getBoundingClientRect();
      const viewportWidth = window.innerWidth;
      const tooltipWidth = 350; // 최대 너비 설정값

      // 화면 오른쪽 경계를 벗어날 경우
      if (rect.left + tooltipWidth / 2 > viewportWidth) {
        setTooltipPos({ left: 'auto', right: '0', transform: 'none' });
      }
      // 화면 왼쪽 경계를 벗어날 경우
      else if (rect.left - tooltipWidth / 2 < 0) {
        setTooltipPos({ left: '0', right: 'auto', transform: 'none' });
      }
      // 중앙 유지
      else {
        setTooltipPos({ left: '50%', right: 'auto', transform: 'translateX(-50%)' });
      }
    }
  };

  const handleMenuClick = (menu, label) => {
    setActiveMenu(menu);
    onMenuType(menu, label);
  };

  return (
    <header style={headerStyle}>
      <div style={logoStyle}>
        <span style={logoIconStyle}>📊</span>
        <span style={logoTextStyle}>DEVICE SOLUTION</span>
      </div>

      <nav style={navStyle}>
        {menuItems.map((item) => (
          <div
            key={item.id}
            ref={(el) => (containerRefs.current[item.id] = el)} // 참조 저장
            style={{ position: 'relative', display: 'inline-block' }}
            onMouseEnter={() => handleMouseEnter(item.id)}
            onMouseLeave={() => setHoveredItem(null)}
          >
            <button
              onClick={() => handleMenuClick(item.id, item.label)}
              style={{
                ...menuButtonStyle,
                ...(activeMenu === item.id ? activeMenuStyle : {}),
              }}
            >
              {item.label}
            </button>

            {hoveredItem === item.id && (
              <div style={{ ...tooltipStyle, ...tooltipPos }}>
                {Array.isArray(item.tip)
                  ? item.tip.map((line, i) => (
                      <div key={i} style={{ marginBottom: '4px' }}>
                        • {line}
                      </div>
                    ))
                  : item.tip}
                <div style={tooltipArrowStyle} />
              </div>
            )}
          </div>
        ))}
      </nav>

      <div style={rightSectionStyle}>
        {/* Copyrights 버튼 추가 */}
        <button
          title="License Information"
          style={copyrightButtonStyle}
          onClick={() => {
            // 여기에 이동 로직 추가 (예: onMenuType('Copyrights', 'Copyrights'))
            if (onMenuType) onMenuType('Copyrights', 'Copyrights');
          }}
        >
          <span style={{ fontSize: '12px' }}>©</span>
          <span>Copyrights</span>
        </button>
        <div style={selectWrapperStyle}>
          <span style={selectLabelStyle}>Data Source</span>
          <select name="dataType" onChange={(e) => onDataType(e.target.value)} style={selectStyle}>
            <option value="Gen">Simulation (Gen)</option>
            <option value="Api">Live Database (Api)</option>
          </select>
        </div>
      </div>
    </header>
  );
};

// --- 스타일 수정 핵심 부분 ---
const copyrightButtonStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '5px',
  marginRight: '12px', // Select 박스와의 간격
  padding: '4px 8px',
  background: 'rgba(255, 255, 255, 0.05)',
  border: '1px solid #4a5568',
  borderRadius: '4px',
  color: '#cbd5e0',
  fontSize: '10px',
  fontWeight: '600',
  cursor: 'pointer',
  transition: 'all 0.2s ease',
  outline: 'none',
  textTransform: 'uppercase', // 텍스트를 대문자로 (엔지니어링 툴 느낌)
};

const tooltipStyle = {
  position: 'absolute',
  top: '38px',
  backgroundColor: 'rgba(33, 37, 41, 0.98)',
  color: '#fff',
  padding: '10px 14px',
  borderRadius: '6px',
  fontSize: '11px',
  zIndex: 1000,
  boxShadow: '0 8px 16px rgba(0,0,0,0.4)',
  pointerEvents: 'none',
  border: '1px solid #495057',
  width: 'max-content',
  maxWidth: '380px', // 너무 길어지지 않게 제한
  whiteSpace: 'normal', // 줄바꿈 허용
  wordBreak: 'keep-all', // 단어 단위 줄바꿈
  lineHeight: '1.5',
};

const tooltipArrowStyle = {
  position: 'absolute',
  bottom: '100%',
  left: '50%',
  transform: 'translateX(-50%)',
  borderWidth: '6px',
  borderStyle: 'solid',
  borderColor: 'transparent transparent rgba(33, 37, 41, 0.98) transparent',
};

// --- Styles (Height 60% 조정 버전) ---
const headerStyle = {
  height: '36px', // 60px * 0.6
  padding: '0 16px',
  background: 'linear-gradient(90deg, #1a202c 0%, #2d3748 100%)',
  color: '#e2e8f0',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  boxShadow: '0 1px 5px rgba(0,0,0,0.3)',
  borderBottom: '1px solid #4a5568',
  fontFamily: '"Inter", "Segoe UI", sans-serif',
};

const logoStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
  marginRight: '24px',
};

const logoIconStyle = { fontSize: '14px' };

const logoTextStyle = {
  fontSize: '12px', // 폰트 크기 축소
  fontWeight: '800',
  letterSpacing: '0.5px',
  color: '#63b3ed',
};

const navStyle = {
  display: 'flex',
  gap: '2px',
  flex: 1,
  height: '100%',
  alignItems: 'center',
};

const menuButtonStyle = {
  padding: '4px 10px', // 패딩 축소
  background: 'transparent',
  border: 'none',
  borderRadius: '4px',
  color: '#a0aec0',
  fontSize: '11px', // 폰트 크기 축소
  fontWeight: '600',
  cursor: 'pointer',
  transition: 'all 0.2s ease',
  outline: 'none',
};

const activeMenuStyle = {
  background: '#3182ce',
  color: '#ffffff',
};

const rightSectionStyle = {
  display: 'flex',
  alignItems: 'center',
};

const selectWrapperStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '6px',
  background: 'rgba(255,255,255,0.05)',
  padding: '2px 8px', // 내부 여백 축소
  borderRadius: '4px',
  border: '1px solid #4a5568',
};

const selectLabelStyle = {
  fontSize: '9px', // 라벨 크기 축소
  color: '#718096',
  textTransform: 'uppercase',
  fontWeight: 'bold',
};

const selectStyle = {
  background: 'transparent',
  color: '#ffffff',
  border: 'none',
  fontSize: '11px', // 폰트 크기 축소
  fontWeight: '500',
  cursor: 'pointer',
  outline: 'none',
};
export default HeaderMenu;
