import { useEffect, useMemo, useRef, useState, useCallback } from 'react';
import { generateParulaColors } from '../utils/ColorGenerator';

const MetroMap = ({
  params,
  waferDatas,
  onUpdate,
  isDetail,
  zoomScale = 1,
  zoomOffset = { x: 0, y: 0 },
  isZoomInMode,
  onZoomChange,
  interactionMode, // 'select' 또는 'drag' 추가
}) => {
  const canvasRef = useRef(null);
  const [hoverInfo, setHoverInfo] = useState({ active: false, type: '', data: null, px: 0, py: 0 });
  const [dragStart, setDragStart] = useState(null);
  const [dragEnd, setDragEnd] = useState(null);
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const { waferSize, waferPixelSize, mapType } = params;
  let center = waferPixelSize / 2;

  // 1. 색상 그라데이션 생성
  const stepCount = 100;
  let colors = useMemo(() => generateParulaColors(stepCount), []);
  colors = params.colors && params.colors.length > 0 ? params.colors : colors;

  // 2. [추가] 색상 매핑을 위한 최소/단계 값 계산
  const colorMetrics = useMemo(() => {
    const min = waferDatas.min || 0;
    const max = waferDatas.max || 100;
    const step = (max - min) / stepCount || 1;
    return { min, step };
  }, [waferDatas.min, waferDatas.max]);

  // 3. 툴팁 초기화
  const clearHover = useCallback(() => {
    setHoverInfo({ active: false, type: '', data: null, px: 0, py: 0 });
    if (onUpdate) onUpdate('info...');
  }, [onUpdate]);

  const handleStart = (e) => {
    const pos = getMousePos(e);

    if (isZoomInMode) {
      setDragStart(pos);
    } else if (interactionMode === 'drag' || zoomScale > 1) {
      setIsPanning(true);
      setPanStart({ x: pos.screenX, y: pos.screenY });
    }
  };

  const handleMove = (e) => {
    const pos = getMousePos(e);

    // 1. ZoomBox 모드
    if (isZoomInMode && dragStart) {
      setDragEnd(pos);
      clearHover();
      return;
    }

    // 2. Drag(Pan) 모드
    if (interactionMode === 'drag' && isPanning) {
      const dx = (pos.screenX - panStart.x) / finalScale;
      const dy = (pos.screenY - panStart.y) / finalScale;
      onZoomChange(zoomScale, {
        x: zoomOffset.x - dx,
        y: zoomOffset.y + dy,
      });
      setPanStart({ x: pos.screenX, y: pos.screenY });
      return;
    }

    // 3. Select 모드 (툴팁) - 기본값이 select이므로 명시적으로 체크
    if (interactionMode === 'select' || (!isZoomInMode && interactionMode !== 'drag')) {
      const { x: dataX, y: dataY, screenX, screenY } = pos;
      const threshold = 10 / finalScale;

      const found = waferDatas.dataList?.find(
        (d) => Math.sqrt((d.x - dataX) ** 2 + (d.y - dataY) ** 2) < threshold,
      );

      if (found) {
        setHoverInfo({ active: true, type: mapType, data: found, px: screenX, py: screenY });
        if (onUpdate) onUpdate(`ID: ${found.id}, Value: ${found.cdvalue?.toFixed(2)}`);
      } else {
        clearHover();
      }
    }
  };
  const handleEnd = () => {
    setIsPanning(false);

    if (isZoomInMode && dragStart && dragEnd) {
      // 1. 드래그한 영역의 가로/세로 길이 계산 (데이터 좌표계 mm)
      const dx = Math.abs(dragEnd.x - dragStart.x);
      const dy = Math.abs(dragEnd.y - dragStart.y);

      // 2. 가로/세로 중 "더 긴 쪽"을 기준으로 잡아야 화면의 "짧은 쪽"에 꽉 찹니다.
      const dragSize = Math.max(dx, dy);

      // 최소 드래그 거리 (노이즈 방지)
      if (dragSize > 1) {
        /* 계산식 원리:
         새로운 줌 배율 = 전체 웨이퍼 크기 / 내가 선택한 영역 크기
         예: 300mm 웨이퍼에서 100mm 영역을 드래그했다면, 3배 확대(300/100)가 되어야 꽉 참.
      */
        const newZoomScale = waferSize / dragSize;

        // 3. 중심점(Offset)은 드래그한 박스의 정중앙
        const newOffsetX = (dragStart.x + dragEnd.x) / 2;
        const newOffsetY = (dragStart.y + dragEnd.y) / 2;

        onZoomChange(newZoomScale, { x: newOffsetX, y: newOffsetY });
      }
    }
    setDragStart(null);
    setDragEnd(null);
  };

  // 1. 기본 배율과 사용자 줌 배율을 결합
  // 1. 기본 배율 (웨이퍼가 캔버스에 꽉 차는 배율)
  const baseScale = useMemo(() => {
    if (!waferSize || !waferPixelSize) return 1;
    // 마진(20px)을 제외한 가용 영역 계산
    return (waferPixelSize - 42) / waferSize;
  }, [waferSize, waferPixelSize]);

  // 2. 최종 배율 (기본 배율 * 사용자 줌 배율)
  const finalScale = useMemo(() => {
    // zoomScale이 0 이하로 내려가지 않도록 보호
    const safeZoom = Math.max(zoomScale, 0.1);
    return baseScale * safeZoom;
  }, [baseScale, zoomScale]);

  // 마우스 위치를 데이터 좌표로 역산 (줌/오프셋 반영)
  const getMousePos = useCallback(
    (e) => {
      if (!canvasRef.current) return { x: 0, y: 0 };
      const rect = canvasRef.current.getBoundingClientRect();
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;

      const mx = clientX - rect.left;
      const my = clientY - rect.top;

      // 데이터 좌표계 변환
      const dx = (mx - center) / finalScale + zoomOffset.x;
      const dy = (center - my) / finalScale + zoomOffset.y;

      return { x: dx, y: dy, rawX: mx, rawY: my, screenX: clientX, screenY: clientY };
    },
    [center, finalScale, zoomOffset],
  );

  // 색상을 받아서 30% 정도 어둡게 만들어 테두리 색상으로 반환하는 함수
  const getStrokeColor = (hex) => {
    const darken = 0.1; // 밝기 비율
    let r = parseInt(hex.slice(1, 3), 16);
    let g = parseInt(hex.slice(3, 5), 16);
    let b = parseInt(hex.slice(5, 7), 16);

    r = Math.floor(r * darken);
    g = Math.floor(g * darken);
    b = Math.floor(b * darken);

    return `rgb(${r}, ${g}, ${b})`;
  };

  // 도형 그리기 함수
  const drawShape = (ctx, x, y, size, fillColor, type) => {
    const strokeColor = getStrokeColor(fillColor);

    ctx.beginPath();
    ctx.fillStyle = fillColor;
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = 0.8;

    switch (type) {
      case 'rect': // 사각형
        ctx.rect(x - size, y - size, size * 2, size * 2);
        break;
      case 'circle': // 원
        ctx.arc(x, y, size, 0, Math.PI * 2);
        break;
      case 'diamond': // 마름모
        ctx.moveTo(x, y - size);
        ctx.lineTo(x + size, y);
        ctx.lineTo(x, y + size);
        ctx.lineTo(x - size, y);
        break;
      case 'tri-up': // 정삼각형
        ctx.moveTo(x - size, y - size);
        ctx.lineTo(x + size, y - size);
        ctx.lineTo(x, y + size);
        break;
      case 'tri-down': // 역삼각형
        ctx.moveTo(x, y - size);
        ctx.lineTo(x + size, y + size);
        ctx.lineTo(x - size, y + size);
        break;
      case 'tri-left': // 왼쪽 삼각형
        ctx.moveTo(x + size, y - size);
        ctx.lineTo(x + size, y + size);
        ctx.lineTo(x - size, y);
        break;
      case 'tri-right': // 오른쪽 삼각형
        ctx.moveTo(x - size, y - size);
        ctx.lineTo(x + size, y);
        ctx.lineTo(x - size, y + size);
        break;
      default:
        break;
    }

    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  };

  // 5. 캔버스 그리기 (핵심)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !waferDatas) return;

    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    canvas.width = waferPixelSize * dpr;
    canvas.height = waferPixelSize * dpr;
    ctx.scale(dpr, dpr);

    ctx.clearRect(0, 0, waferPixelSize, waferPixelSize);
    ctx.save();

    // [Step 1] 좌표계 변환: 화면 중심 이동 -> Y축 반전 -> 줌/오프셋 적용
    ctx.translate(waferPixelSize / 2, waferPixelSize / 2);
    ctx.scale(finalScale, -finalScale);
    ctx.translate(-zoomOffset.x, -zoomOffset.y);

    // 선 두께 보정값 (줌을 많이 해도 선이 너무 굵어지지 않게 함)
    const strokeWeight = 1 / finalScale;

    // [Step 2] 웨이퍼 외곽선 및 Notch 그리기
    ctx.beginPath();
    const radius = waferSize / 2;
    const notchSize = waferSize * 0.02; // 웨이퍼 크기의 2% 정도

    // 원형 외곽선 (Notch 부분을 살짝 비우고 그려도 되지만, 보통 덧그리는 방식 사용)
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.lineWidth = strokeWeight;
    ctx.strokeStyle = '#334155';
    ctx.stroke();

    // Notch (웨이퍼 하단 중앙 기준 V자 홈)
    ctx.beginPath();
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(-notchSize / 2, -radius - 1000, notchSize, notchSize * 1.2);

    ctx.moveTo(-notchSize / 2, -radius);
    ctx.lineTo(0, -radius + notchSize);
    ctx.lineTo(notchSize / 2, -radius);
    ctx.fillStyle = '#ffffff'; // 배경색으로 채워 홈처럼 보이게 함
    ctx.fill();
    ctx.stroke();
    // [Step 3] Die Grid (격자) 그리기
    ctx.beginPath();
    ctx.lineWidth = 1 / finalScale; // 다이 경계선은 더 가늘게
    ctx.strokeStyle = 'rgba(187, 187, 202, 0.6)'; // 연한 회색

    waferDatas.dieList.forEach((die) => {
      // die.x, die.y는 보통 다이의 좌측 하단 기준
      ctx.strokeRect(die.x, die.y, die.width, die.height);
    });

    // [Step 4] 데이터 포인트 (CD Value) 그리기
    const { min, step } = colorMetrics;
    waferDatas.dataList?.forEach((cd) => {
      const colorIdx = Math.floor((cd.cdvalue - min) / step);
      ctx.fillStyle = colors[Math.max(0, Math.min(99, colorIdx))];
      ctx.beginPath();
      let x = cd.x;
      let y = cd.y;
      let size = 1500; // 기본 크기

      // 도형 그리기 호출부 수정 => type 추가 전달
      drawShape(ctx, x, y, size, colors[Math.max(0, Math.min(99, colorIdx))], params.pointStyle);
      // 점 크기는 고정 픽셀 느낌을 주기 위해 scale의 역수를 곱함
      //ctx.arc(cd.x, cd.y, (500 * params.pointSize) / zoomScale, 0, Math.PI * 2);
      //ctx.fill();
    });

    ctx.restore();

    // [Step 5] Zoom Box (화면 좌표계 - 줌 영향 없음)
    if (dragStart && dragEnd) {
      ctx.strokeStyle = '#3b82f6';
      ctx.setLineDash([4, 4]);
      ctx.lineWidth = 1;
      ctx.strokeRect(
        dragStart.rawX,
        dragStart.rawY,
        dragEnd.rawX - dragStart.rawX,
        dragEnd.rawY - dragStart.rawY,
      );
      ctx.setLineDash([]);
    }
  }, [
    waferPixelSize,
    waferDatas,
    finalScale,
    zoomOffset,
    dragEnd,
    colors,
    colorMetrics,
    waferSize,
    zoomScale,
    center,
  ]);

  // 데이터가 없을 때의 얼리 리턴 (모든 Hook 호출 이후)
  if (!waferDatas || !waferDatas.dataList) return null;

  return (
    <div style={containerStyle}>
      <canvas
        ref={canvasRef}
        width={waferPixelSize}
        height={waferPixelSize}
        onMouseDown={handleStart}
        onMouseMove={handleMove} // handleMove로 변경됨
        onMouseUp={handleEnd}
        onMouseLeave={() => {
          handleEnd();
          clearHover();
        }}
        onTouchStart={handleStart} // 모바일 터치 추가
        onTouchMove={handleMove} // 모바일 터치 추가
        onTouchEnd={handleEnd} // 모바일 터치 추가
        style={{
          display: 'block',
          // 모드에 따른 커서 정밀 제어
          cursor: isZoomInMode ? 'crosshair' : interactionMode === 'drag' ? 'grab' : 'default',
          touchAction: 'none',
        }}
      />

      {/* 예쁜 툴팁 */}
      {hoverInfo.active && (
        <div style={tooltipStyle(hoverInfo.px, hoverInfo.py)}>
          <div style={tooltipHeaderStyle}>{hoverInfo.type} DATA</div>
          <div style={tooltipGridStyle}>
            <span style={labelStyle}>ID:</span> <span style={valueStyle}>{hoverInfo.data.id}</span>
            <span style={labelStyle}>X/Y:</span>{' '}
            <span style={valueStyle}>
              {hoverInfo.data.x.toFixed(0)}/{hoverInfo.data.y.toFixed(0)}
            </span>
            <span style={labelStyle}>Value:</span>{' '}
            <span style={{ ...valueStyle, color: '#60a5fa' }}>
              {hoverInfo.data.cdvalue?.toFixed(2)}
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

// --- 스타일 정의 ---

const containerStyle = {
  width: '100%',
  height: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  overflow: 'hidden',
  position: 'relative', // 툴팁이나 드래그 UI의 기준점이 됩니다.
};

const tooltipStyle = (x, y) => ({
  position: 'fixed',
  left: x + 15,
  top: y + 15,
  backgroundColor: 'rgba(15, 23, 42, 0.9)',
  backdropFilter: 'blur(6px)',
  color: '#fff',
  padding: '12px',
  borderRadius: '8px',
  fontSize: '12px',
  pointerEvents: 'none',
  zIndex: 9999,
  border: '1px solid rgba(255,255,255,0.1)',
  boxShadow: '0 10px 15px -3px rgba(0,0,0,0.5)',
});

const tooltipHeaderStyle = {
  color: '#38bdf8',
  fontSize: '10px',
  fontWeight: '800',
  marginBottom: '6px',
  letterSpacing: '0.5px',
};
const tooltipGridStyle = { display: 'grid', gridTemplateColumns: 'auto auto', gap: '2px 10px' };
const labelStyle = { color: '#94a3b8', fontWeight: '500' };
const valueStyle = { fontWeight: 'bold', fontFamily: 'monospace' };

export default MetroMap;
